from pathlib import Path
import hashlib,json,sqlite3,stat,sys
out=Path(__file__).resolve().parent;f=json.loads((out/'fixture.json').read_text());root=Path(f['workspace_root']);files={str(p.relative_to(root)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in root.rglob('*') if p.is_file()};assert files==json.loads((out/'repository-before.json').read_text());c=sqlite3.connect('file:'+f['state']+'/state.db?mode=ro',uri=True);records={'operations':dict(c.execute('select id,payload from write_operations')),'batches':dict(c.execute("select key,value from state where key like 'batch:%'"))};assert records==json.loads((out/'records-before.json').read_text());assert set(c.execute('select worktree_id,revoked from write_trust'))=={(f['entries'][f[k]],1 if k=='parent' else 0) for k in ['parent','middle','leaf']};assert c.execute('pragma integrity_check').fetchone()[0]=='ok';raw=json.loads(c.execute('select status from membership where workspace_id=? and worktree_id=?',(f['workspace'],f['entries'][f['parent']])).fetchone()[0]);assert raw['index_gitlinks'][0]['oid']['hex']=='949253cc316c4811271f4eb272f1196a8027d10e';proof={'exact_repository_files_modes':True,'exact_old_operations_batches_no_replay':True,'no_new_trust_parent_revoked':True,'parent_index_gitlink_recorded':raw['index_gitlinks'][0],'integrity':'ok'};label=sys.argv[1];(out/('native-proof-'+label+'.json')).write_text(json.dumps(proof,indent=2)+'\n');print(proof)
